struct FileHandle: ~Copyable {
    private let fd: Int32
    init(path: String) { fd = open(path, O_RDONLY) }
    borrowing func read(_ n: Int) -> Data { /* uses fd; caller keeps ownership */ return Data() }
    consuming func close() { closeDescriptor(fd); discard self }  // at most once
    deinit { closeDescriptor(fd) }                                // only if never closed
}

